dslRule:
isAutoBuilding() && hasJdtCoreSettings($args$) && !DISABLE_AUTO_BUILDING_ON_SETTINGS_CHANGE
=> isAutoBuilding() && hasJdtCoreSettings($args$) && fProject != null && !DISABLE_AUTO_BUILDING_ON_SETTINGS_CHANGE
;;

beforeExample:
class OptionsConfigurationBlock {
    Object fProject;
    static final boolean DISABLE_AUTO_BUILDING_ON_SETTINGS_CHANGE = false;

    boolean isAutoBuilding() { return true; }
    boolean hasJdtCoreSettings(Object changedOptions) { return true; }

    void calculateAutoBuild(Object changedOptions) {
        boolean isAutoBuildOn = isAutoBuilding();
        boolean hasJdtCoreSettings = hasJdtCoreSettings(changedOptions);
        boolean willAutoBuild = isAutoBuildOn && hasJdtCoreSettings && !DISABLE_AUTO_BUILDING_ON_SETTINGS_CHANGE;
    }
}

